document.addEventListener('submit',async e=>{const formId=e.target.getAttribute('id');if(!['modal-form','settings-form','writer-form','prompt-form'].includes(formId))return;e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');if(button)button.disabled=true;try{const x=Object.fromEntries(new FormData(form));
 if(formId==='writer-form'){await saveWriter();return;}
 if(formId==='prompt-form'){const prompt={id:x.id||undefined,name:x.name,note:x.note,text:x.text,types:Object.keys(types).filter(t=>form.elements.namedItem('type-'+t)?.checked),isDefault:form.elements.isDefault.checked};await act('savePrompt',{prompt},prompt.id?'프롬프트를 수정했어요.':'프롬프트를 추가했어요.');promptEditing=null;render();return;}
 if(formId==='settings-form'){x.motion=form.elements.motion.checked;await act('saveSettings',{settings:x});render();return;}
 if(modalKind==='publicationSelect'){closeModal();publicationModal(x.itemId);return;}
 if(modalKind==='publication'){const i=S.items.find(i=>i.id===x.itemId);const images=(i?.attachmentIds||[]).filter(id=>form.elements.namedItem('include-'+id)?.checked).map(id=>({fileId:id,afterParagraph:Number(form.elements.namedItem('position-'+id).value),rights:form.elements.namedItem('rights-'+id).value,licenseUrl:form.elements.namedItem('license-'+id).value,caption:form.elements.namedItem('caption-'+id).value}));await act('preparePublication',{itemId:x.itemId,requestId:x.requestId,title:x.title,lane:i?.automaticLane||'manual',scheduledAt:x.scheduledAt,reviewed:form.elements.reviewed.checked,images},'발행 준비를 저장했어요. 검사 결과는 발행 관리에서 확인해요.');closeModal();navigate('publishing');return;}
 if(modalKind==='item'){if(!x.id)delete x.id;x.prep={photos:form.elements.photos.checked,outline:form.elements.outline.checked,body:form.elements.body.checked};x.locked=form.elements.locked.checked;await act('saveItem',{item:x});}
 else if(modalKind==='delete')await act('deleteItem',{id:x.id},'글감을 삭제했어요.');
 else if(modalKind==='bulk'){const r=await act('bulkAdd',x,null);toast(r.count+'개 글감을 등록했어요.');}
 else if(modalKind==='sponsor'){if(!x.id)delete x.id;await act('saveSponsor',{sponsor:x});}
 else if(modalKind==='lesson'){if(!x.id)delete x.id;x.active=form.elements.active.checked;x.files=lessonFiles;await act('saveLesson',{lesson:x},'학습 페이지를 저장했어요.');}
 else if(modalKind==='schedule'){const r=await act('schedule',{options:{start:x.start,days:Number(x.days),daily:Number(x.daily),onlyOverdue:x.onlyOverdue==='yes',useKeywords:form.elements.useKeywords.checked}},null);toast(r.changes.length+'개 일정 조정 · 확인 알림 '+r.notices.length+'개');}
 else if(modalKind==='naver'){await act('importNaver',{snapshot:JSON.parse(x.snapshot)},'네이버 통계를 저장했어요.');}
 else if(modalKind==='metrics'){const file=form.elements.file.files[0],rows=parseCSV(await file.text());const r=await act('importMetrics',{rows},null);toast(r.count+'행 추가 · '+r.updated+'행 갱신 · '+r.skipped+'행 제외'+(r.invalidFields?' · 잘못된 지표 '+r.invalidFields+'개':'')+(r.unlinked?' · 글 미연결 '+r.unlinked+'행':''));}
 closeModal();render();
 }catch(err){toast(err.message);}finally{if(button)button.disabled=false;}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='channel'){channel=el.value;render();}
 else if(el.id==='status-filter'){filterStatus=el.value;contentPage=0;render();}
 else if(el.id==='writer-prompt'){writerPromptChoice=el.value;}
 else if(el.id==='writer-type'){writerBuffer=getWriter();render();}
 else if(el.id==='lesson-upload'&&el.files[0]){const file=el.files[0],f=await upload(file);lessonFiles.push(f.id);document.getElementById('lesson-files').insertAdjacentHTML('beforeend',`<a class="badge" href="/api/files/${f.id}">${esc(f.name)}</a>`);if(file.type==='text/plain'||file.name.endsWith('.md'))document.querySelector('.modal [name="source"]').value+= '\n'+await file.text();toast('자료 파일을 저장했어요.');}
 else if(el.id==='writer-upload'&&el.files[0]){const f=await upload(el.files[0]);const notes=document.querySelector('[name="photoNotes"]');notes.value+='\n첨부: '+f.name+' (자료 ID '+f.id+')';const field=document.querySelector('[name="attachmentIds"]');field.value=JSON.stringify([...JSON.parse(field.value),f.id]);refreshWriterCounts();toast('자료 파일을 저장했어요.');}
 }catch(err){toast(err.message);}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.id==='search'){filterText=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const position=e.target.selectionStart;contentPage=0;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(position,position);},250);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();drawerOpen=false;document.querySelector('.drawer')?.remove();document.querySelector('.sidebar')?.classList.remove('open');}});
try{await load();const [r,id]=location.hash.replace('#','').split('/');route=paths[r]?r:'home';editing=id||null;render();if(route==='writer')writerBaseline=JSON.stringify(getWriter());}catch(e){document.getElementById('app').innerHTML=`<div class="boot"><div>사이트를 열지 못했어요.<br><br>${esc(e.message)}<br><br><button onclick="location.reload()">다시 시도</button></div></div>`;}

function recommendationRow(r){
 const evidence=r.evidence.map(k=>`<span class="badge">${esc(k.keyword)} · ${k.percentage.toFixed(2)}%</span>`).join('');
 return `<article class="recommendation-row"><div class="recommendation-main"><div class="pill-list"><span class="badge gray">${r.kind==='existing'?'보관함 글감':'새 글감 제안'}</span>${r.region?`<span class="badge gray">${esc(r.region)}</span>`:''}</div><h3>${esc(r.title)}</h3><div class="pill-list">${evidence}</div><p>${r.reasons.map(esc).join('<br>')}</p>${r.cautions.length?`<p class="recommendation-caution">${r.cautions.map(esc).join('<br>')}</p>`:''}${r.relatedPublished?.length?`<p class="muted">관련 게시글: ${r.relatedPublished.map(i=>btn('writeItem',esc(i.title),'ghost tiny',`data-id="${esc(i.id)}"`)).join('')}</p>`:''}</div><div class="recommendation-actions">${btn('chooseRecommendation',r.kind==='existing'?'이 글감으로 쓰기':'글감 등록·쓰기','primary tiny',`data-id="${esc(r.id)}"`)}${btn('planRecommendation','발행일 정하기','tiny',`data-id="${esc(r.id)}"`)}</div></article>`;
}
function managerReportsPanel(){
 const reports=(S.managerReports||[]).filter(r=>r.kind===(reportRange==='week'?'weekly':'daily')).slice(0,4),schedule=S.managerSchedules?.[reportRange==='week'?'weekly':'daily'];
 return panel('매니저가 남긴 리포트',`<div class="panel-body"><p class="muted">${schedule?esc(schedule.label):'자동 리포트 예약 전'} · 결과는 알림 센터에도 남아요.</p>${reports.map(r=>`<article class="event-card"><span class="badge">${r.kind==='weekly'?'주간 리포트·추천 기준 검토':'일일 리포트'}</span><p><strong>${esc(r.summary)}</strong></p><p>${esc(r.start)} ~ ${esc(r.end)} · ${r.automatic?'자동 실행':'직접 실행'}</p>${r.visitorAverage!==null?`<p>실제 통계 ${r.visitorDays}일의 하루 평균 ${fmt(Math.round(r.visitorAverage))}명</p>`:''}${r.deadlines.length?`<p>3일 이내 발행 마감: ${r.deadlines.map(d=>esc(d.title)+' ('+esc(d.date)+')').join(', ')}</p>`:''}${r.warnings.map(w=>`<p class="recommendation-caution">${esc(w)}</p>`).join('')}${r.refresh?`<details><summary>과거 글 재작성 점검 · ${r.refresh.candidateCount}개 후보</summary>${r.refresh.candidates.map(c=>`<p>${esc(c.title)} · ${esc(c.basisLabel)} 관측 평균 ${c.peak.average.toFixed(1)} → ${c.recent.average.toFixed(1)} · ${(c.decline*100).toFixed(0)}% 감소</p>`).join('')}${r.refresh.warnings.map(w=>`<p class="muted">${esc(w)}</p>`).join('')}${btn('navigate','재작성 추천 보기','tiny','data-route="refresh"')}</details>`:''}${r.memory?`<details><summary>이번 주 검토 근거</summary><p>${esc(r.memory.summary)}</p><p>${esc(r.memory.changes)}</p><p class="muted">실제 글별 지표가 충분할 때만 소재 참고 점수를 조정해요. 고정 글쓰기 원칙은 유지합니다.</p></details>`:''}<small>${esc(new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(r.at)))} · 한국 시간</small></article>`).join('')||'<p class="muted">아직 저장된 리포트가 없어요.</p>'}</div>`,btn('createReport','지금 리포트 저장','tiny'));
}
function recommendationPanel(compact=false){
 const r=recommendations,rows=compact?(r.existing.length?r.existing:r.ideas).slice(0,3):r.existing;
 return panel('유입 검색어로 고른 글감',`<div class="panel-body">${r.keywordDate?`<p class="muted">검색어 기준 ${esc(r.keywordDate)} · 네이버가 표시한 유입 비율</p>`:''}${r.warnings.map(w=>`<div class="notice ${r.stale?'recommendation-caution':''}">${esc(w)}</div>`).join('')}${rows.length?`<div class="recommendation-list">${rows.map(recommendationRow).join('')}</div>`:empty(r.keywordDate?'날짜 미정 보관함에서 맞는 글감이 없어요. 새 글감 제안을 살펴보세요.':'통계가 저장되면 실제 검색어로 글감을 추천해요.')}<p class="muted">내 블로그의 유입을 참고해요. 전체 검색량·급상승 여부·예상 조회수는 확인되지 않았어요.</p></div>`,btn('navigate',compact?'추천 전체 보기 →':'통계 보기 →','ghost tiny',`data-route="${compact?'recommendations':'analytics'}"`),true);
}
function trendDate(value){return value?new Date(value).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})+' KST':'아직 확인 전';}
function trendPanel(compact=false){
 const all=trends.rows||[],rows=(compact||trendScope==='travel'?all.filter(r=>['travel','shopping'].includes(r.scope)):all).slice(0,compact?3:30);
 const controls=compact?btn('navigate','키워드 전체 →','ghost tiny','data-route="recommendations"'):btn('refreshTrends',trendRefreshing?'확인 중…':'최신 키워드 확인','tiny',trendRefreshing?'disabled':'');
 return `<div class="trend-host" data-compact="${compact?'true':'false'}">`+panel('지금 쓰기 좋은 외부 키워드',`<div class="panel-body"><p class="muted">화면을 열면 확인 · 15분 간격 갱신 · 마지막 시도 ${esc(trendDate(trends.lastAttemptAt))}</p>${!compact?`<div class="pill-list">${btn('trendScope','여행·쇼핑',trendScope==='travel'?'primary tiny':'tiny','data-scope="travel"')}${btn('trendScope','전체 키워드',trendScope==='all'?'primary tiny':'tiny','data-scope="all"')}</div>`:''}${(trends.warnings||[]).map(w=>`<div class="notice recommendation-caution">${esc(w)}</div>`).join('')}${rows.length?rows.map(r=>`<article class="recommendation-row"><div class="recommendation-main"><div class="pill-list"><span class="badge">추천 우선순위 ${r.score}/100</span><span class="badge gray">${r.search?'Google 급상승 피드':'뉴스 기반 글감'}</span>${r.region!=='미분류'?`<span class="badge gray">${esc(r.region)}</span>`:''}${r.stale?'<span class="badge gray">자료 갱신 필요</span>':''}</div><h3>${esc(r.keyword)}</h3><p>${r.search?`Google 피드 표시 검색량: ${esc(r.search.label||'미제공')} · 근사치 · 집계 기간 미표기`:'검색량 미확인'}${r.newsMentions?` · 가져온 기사 표본 ${r.newsMentions}건`:''}${r.blogKeyword?`<br>내 블로그 유입: ${esc(r.blogKeyword.keyword)} · ${r.blogKeyword.percentage.toFixed(2)}%`:''}</p><p>${r.reasons.map(esc).join('<br>')}</p>${r.cautions.length?`<p class="recommendation-caution">${r.cautions.map(esc).join('<br>')}</p>`:''}<details class="details"><summary>근거·확인 시각 보기</summary>${r.evidence.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)}</a><br><span class="muted">${esc(e.publisher||trends.sources.find(s=>s.id===e.sourceId)?.name||'뉴스 피드')} · 자료 ${esc(trendDate(e.publishedAt))} · 수집 ${esc(trendDate(e.sourceCheckedAt))}</span></p>`).join('')}<p class="muted">점수 구성: 최신성 ${r.scoreParts.freshness}, 검색 신호 ${r.scoreParts.searchSignal}, 기사 표본 ${r.scoreParts.newsSignal}, 블로그 유입 ${r.scoreParts.blogSignal}, 분야 적합도 ${r.scoreParts.fit}, 준비 ${r.scoreParts.ready} · 중복 −${r.scoreParts.overlapPenalty}, 같은 지역 −${r.scoreParts.regionPenalty}, 오래된 수집 −${r.scoreParts.stalePenalty}</p></details></div><div class="recommendation-actions">${btn('chooseTrendRecommendation',r.relatedItems.length?'기존 글감으로 쓰기':'글감 등록·쓰기','primary tiny',`data-id="${esc(r.id)}"`)}</div></article>`).join(''):empty(trends.lastAttemptAt?'현재 표본에 맞는 여행·쇼핑 키워드가 없어요. 전체 키워드도 확인할 수 있어요.':'최신 자료를 확인하면 외부 키워드와 근거가 여기에 표시돼요.')}${!compact?`<details class="details"><summary>연결된 지표와 추천 기준</summary><p class="muted">${esc(trends.notice||'추천 점수는 검색량이나 예상 조회수가 아닙니다.')}</p>${(trends.providers||[]).map(p=>`<p>${esc(p.name)} · ${p.connected?'수집 자료 있음':'연동 전'}<br><span class="muted">${esc(p.measure)}</span></p>`).join('')}<p class="muted">글감 등록은 일정·원고를 자동 발행하지 않아요. 기사 내용은 작성 전에 공식 정보로 확인해 주세요.</p></details>`:''}</div>`,controls,true)+'</div>';
}
async function refreshTrends(silent=false){
 if(trendRefreshing||document.hidden)return;
 trendRefreshing=true;document.querySelectorAll('[data-action="refreshTrends"]').forEach(b=>{b.disabled=true;b.textContent='확인 중…';});
 try{const data=await api('/api/trends-agent',{op:'refresh'});trends=data.trends;if(!silent)toast(data.cached?'15분 안에 확인한 최신 저장 자료를 보여드려요.':'외부 키워드와 수집 근거를 갱신했어요.');}
 catch(e){if(!silent)toast(e.message);}
 finally{trendRefreshing=false;document.querySelectorAll('.trend-host').forEach(host=>{host.outerHTML=trendPanel(host.dataset.compact==='true');});}
}
function requestVisibleTrends(){if(['home','recommendations'].includes(route)&&!document.hidden&&(!trends.lastAttemptAt||Date.now()-Date.parse(trends.lastAttemptAt)>=15*60000))refreshTrends(true);}
setInterval(requestVisibleTrends,15*60000);
document.addEventListener('visibilitychange',requestVisibleTrends);

function recommendationPage(){
 const selected=S.items.filter(i=>i.recommendationSource).sort((a,b)=>b.recommendationSource.selectedAt.localeCompare(a.recommendationSource.selectedAt));
 const followup=selected.slice(0,15).map(i=>{const metrics=analyticsRows.filter(m=>m.id===i.id),sum=k=>{const values=metrics.filter(m=>m[k]!==null);return values.length===1?values[0][k]:null;};return `<tr><td>${esc(i.title)}<span class="table-sub">${esc(i.recommendationSource.keywordDate)} · ${i.recommendationSource.keywords.map(k=>esc(k.keyword)).join(', ')}</span></td><td>${statusBadge(i.status)}</td><td>${metricDisplay(sum('visits'))}</td><td>${metricDisplay(sum('clicks'))}</td><td>${metricDisplay(sum('revenue'),'원')}</td><td>${btn('writeItem','열기','tiny',`data-id="${esc(i.id)}"`)}</td></tr>`;}).join('');
 return head('키워드 분석·글감 추천','외부 트렌드와 내 블로그 유입을 함께 살펴봐요.',btn('navigate','과거 글 재작성','', 'data-route="refresh"')+btn('navigate','콘텐츠 보관함','', 'data-route="contents"'))+trendPanel()+recommendationPanel()+panel('보관함에 없는 새 글감',`<div class="panel-body">${recommendations.ideas.length?recommendations.ideas.map(recommendationRow).join(''):empty('기존 글감으로 다룰 수 있는 검색어예요. 위 추천 목록을 확인해 주세요.')}<p class="muted">관련 게시글을 보여주는 것은 제목·키워드의 연결입니다. 해당 글에서 유입됐다는 뜻은 아닙니다.</p></div>`)+panel('선택한 추천과 진행 상황',selected.length?`<div class="table-scroll"><table><thead><tr><th>선택한 글감·근거</th><th>상태</th><th>실제 유입</th><th>링크 클릭</th><th>수익</th><th>작업</th></tr></thead><tbody>${followup}</tbody></table></div><p class="panel-body muted">글별 성과는 글감 ID로 연결된 단일 출처의 실측값만 표시해요. 출처가 여러 개면 성과 화면에서 각각 확인해 주세요. 블로그 전체 유입 검색어를 특정 글의 성과로 계산하지 않아요.</p>`:empty('추천을 선택하면 근거와 진행 상태를 기록해요.'));
}

function naverPanel(){
 const n=S.naverStats,actions=btn('importNaver','네이버 통계 가져오기','tiny');
 if(!n)return panel('네이버 방문자·유입 검색어',empty('TinyFish 조회 결과를 가져오면 방문자와 검색어를 확인할 수 있어요.<br>자동 갱신 미연결',actions));
 const rows=n.visitors,last=rows.at(-1),seven=rows.slice(-7),full=seven.length===7&&seven.every((r,i)=>r.date===shifted(seven[0].date,i)),sum=seven.reduce((a,r)=>a+r.count,0);
 return panel('네이버 방문자·유입 검색어',`<div class="panel-body"><div class="notice">${esc(n.source)} · 조회일 ${esc(n.observedAt.slice(0,10))}<br>저장된 조회 결과입니다. ${S.naverSync?.automationId?esc(S.naverSync.schedule)+' · '+esc(S.naverSync.status):'자동 갱신 미연결'}${S.naverSync?.message?' · '+esc(S.naverSync.message):''}${n.keywordDate<day?' · 이전 날짜 자료':''}</div><section class="stats"><div class="stat"><span class="label">최근 순방문자</span><strong>${fmt(last.count)}명</strong><small>${esc(last.date)}</small></div><div class="stat"><span class="label">${full?'7일':'표시 기간'} 일별 순방문자 합계</span><strong>${fmt(sum)}명</strong><small>${esc(seven[0].date)} ~ ${esc(last.date)} · 날짜 간 중복 포함</small></div><div class="stat"><span class="label">${full?'7일':'표시 기간'} 하루 평균</span><strong>${fmt(Math.round(sum/seven.length))}명</strong><small>일별 순방문자 기준</small></div>${n.pageViews?`<div class="stat"><span class="label">조회수</span><strong>${fmt(n.pageViews.count)}회</strong><small>${esc(n.pageViews.date)} · 조회 시점 기준</small></div>`:''}</section><div class="grid-equal"><div><h3>일별 순방문자</h3><div class="table-scroll"><table><thead><tr><th>날짜</th><th>순방문자</th></tr></thead><tbody>${rows.slice(-31).reverse().map(r=>`<tr><td>${esc(r.date)}</td><td>${fmt(r.count)}명</td></tr>`).join('')}</tbody></table></div></div><div><h3>유입 검색어 · ${esc(n.keywordDate)}</h3><div class="table-scroll"><table><thead><tr><th>검색어</th><th>네이버 표시 비율</th></tr></thead><tbody>${n.keywords.map(r=>`<tr><td>${esc(r.keyword)}</td><td>${r.percentage.toFixed(2)}%</td></tr>`).join('')||'<tr><td colspan="2">제공된 검색어 없음</td></tr>'}</tbody></table></div><p class="muted">비율을 방문자 수나 검색 클릭률로 환산하지 않습니다.</p></div></div><p><a href="${esc(n.visitorUrl)}" target="_blank" rel="noopener">네이버 방문 통계</a> · <a href="${esc(n.keywordUrl)}" target="_blank" rel="noopener">네이버 유입 분석</a> · <a href="${esc(n.runUrl)}" target="_blank" rel="noopener">TinyFish 조회 기록</a></p></div>`,actions);
}

function visitorSummary(){
 const rows=(S.naverStats?.visitors||[]).filter(r=>Number.isSafeInteger(r.count)&&r.count>=0&&r.date<day).slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-7);
 const complete=rows.length===7&&rows.every((r,i)=>r.date===shifted(rows[0].date,i));
 const average=complete?rows.reduce((sum,r)=>sum+r.count,0)/7:null;
 return {rows,average,complete,start:rows[0]?.date,end:rows.at(-1)?.date,stale:rows.at(-1)?.date!==shifted(day,-1)};
}
function visitorStatus(){
 const v=visitorSummary(),n=S.naverStats;
 return `<p class="muted">${v.complete?esc(v.start)+' ~ '+esc(v.end)+' · 네이버 일별 순방문자': '연속 7일 통계가 필요해요.'}<br>${n?'조회일 '+esc(n.observedAt.slice(0,10)):'아직 조회 자료가 없어요.'}${v.complete&&v.stale?' · 최신 날짜 집계 대기':''}<br>${S.naverSync?.automationId?esc(S.naverSync.schedule)+' · '+esc(S.naverSync.status):'자동 갱신 미연결'}${S.naverSync?.message?'<br>'+esc(S.naverSync.message):''}</p>`;
}
function visitorGoalBox(){
 const v=visitorSummary(),goal=Math.max(1,Number(S.settings.visitorGoal)||1000),pct=v.complete?v.average/goal*100:null;
 return `<div class="goal-box"><span class="label">네이버 · 7일 평균 하루 방문자</span><div class="n">${v.complete?fmt(Math.round(v.average))+'명':'집계 대기'}</div><p>목표 ${fmt(goal)}명${v.complete?' · '+pct.toFixed(1)+'%':''}</p>${v.complete?`<div class="progress" role="progressbar" aria-label="방문자 목표 달성률" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,pct).toFixed(1)}"><span style="width:${Math.min(100,pct)}%"></span></div>`:''}${visitorStatus()}${btn('navigate','통계 자세히 보기 →','tiny','data-route="analytics"')}</div>`;
}
function visitorMilestone(target){
 const v=visitorSummary();
 return `<span class="badge ${v.complete&&v.average>=target?'green':'gray'}">${!v.complete?'집계 대기':v.average>=target?'기준 충족 · '+esc(v.end):'평균 '+fmt(Math.round(v.average))+'명 / '+fmt(target)+'명'}</span>`;
}

function postStatsPanel(){
 const n=naverPosts;if(!n.stats&&!n.sync)return '';
 return panel('글별 조회수 수집',`<div class="panel-body"><div class="notice">${esc(n.sync?.schedule||'직접 조회 결과')} · ${esc(n.sync?.status||'자료 저장됨')}${n.sync?.message?'<br>'+esc(n.sync.message):''}<br>${fmt(n.trackedPostCount||0)}개 글 · ${fmt(n.stats?.rowCount||0)}일 자료 저장</div>${n.posts.length?`<div class="table-scroll"><table><thead><tr><th>게시글</th><th>최근 확인 날짜</th><th>조회수</th><th>누적 관측일</th><th>작업</th></tr></thead><tbody>${n.posts.slice(0,20).map(p=>`<tr><td><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)}</a><span class="table-sub">${p.publishedDate?'게시일 '+esc(p.publishedDate):'정확한 게시일 미확인'}</span></td><td>${esc(p.latestMeasurement?.date||'—')}</td><td>${metricDisplay(p.latestMeasurement?.views)}</td><td>${fmt(p.measurementDays)}일</td><td>${p.itemId?btn('writeItem','기록 열기','tiny',`data-id="${esc(p.itemId)}"`):'연결 확인 필요'}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="muted">실제 글별 일일 조회수입니다. 검색 유입·클릭률과는 구분해요. 오늘의 진행 중 수치는 비교에서 제외하고 확인한 날짜를 누적 저장합니다.</p>${n.stats?.limitations?.length?`<details><summary>이번 수집의 확인 범위</summary>${n.stats.limitations.map(x=>`<p class="muted">${esc(x)}</p>`).join('')}</details>`:''}</div>`,n.stats?.runUrl?`<a class="refresh-original" href="${esc(n.stats.runUrl)}" target="_blank" rel="noopener">조회 기록 ↗</a>`:'');
}

// Formatting preview: plain text stays the source of truth.
function formattingCSS(style={}){const css=[];if(Number.isFinite(style.fontSizePx)&&style.fontSizePx>=10&&style.fontSizePx<=48)css.push('font-size:'+style.fontSizePx+'px');if(/^#[a-f0-9]{6}$/i.test(style.color||''))css.push('color:'+style.color);if(typeof style.bold==='boolean')css.push('font-weight:'+(style.bold?700:400));if(['left','center','right'].includes(style.alignment))css.push('text-align:'+style.alignment);if(Number.isFinite(style.lineHeight)&&style.lineHeight>=1&&style.lineHeight<=3)css.push('line-height:'+style.lineHeight);return css.join(';');}
function formattingHTML(doc){return doc.blocks.map(p=>{let offset=0,text='';for(const r of p.ranges){text+=esc(p.text.slice(offset,r.start))+`<span style="${esc(formattingCSS(r.style))}">${esc(p.text.slice(r.start,r.end))}</span>`;offset=r.end;}text+=esc(p.text.slice(offset));const tag=p.kind==='quote'?'blockquote':p.kind==='heading'?'h3':'p';return `<${tag} style="${esc(formattingCSS(p.style))}">${text}</${tag}>`;}).join('');}
// End formatting preview render helpers.
async function formattingDraftHash(text){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text||''))),x=>x.toString(16).padStart(2,'0')).join('');}
function formattingWriterPanel(item){return `<details class="details formatting-tools"><summary>써즈 꾸미기 · 인용구 / 색상 / 글자 크기</summary><div class="detail-body"><p class="muted">원고 내용은 그대로 두고 서식만 저장해요. 문장을 선택하거나 꾸밀 문단에 커서를 놓아 주세요.</p><div class="formatting-controls"><label>기준<select id="format-profile"><option value="">글 종류에 맞게 자동 선택</option>${formatting.profiles.map(p=>`<option value="${esc(p.id)}" ${item.formatting?.profileId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>적용 대상<select id="format-target"><option value="paragraph">커서가 있는 문단</option><option value="selection">선택한 문장</option></select></label><label>문단 모양<select id="format-kind"><option value="paragraph">일반 문단</option><option value="heading">소제목</option><option value="quote">인용구</option></select></label><label>글자 크기<select id="format-size"><option value="">기본값 유지</option>${[11,13,15,16,19,24,28,30,34,38].map(n=>`<option value="${n}">${n}px</option>`).join('')}</select></label><label>강조<select id="format-bold"><option value="">기본값 유지</option><option value="true">굵게</option><option value="false">보통</option></select></label><label>정렬<select id="format-align"><option value="">기본값 유지</option><option value="left">왼쪽</option><option value="center">가운데</option><option value="right">오른쪽</option></select></label><label>줄 간격<select id="format-lineheight"><option value="">기본값 유지</option><option value="1.5">1.5</option><option value="1.8">1.8</option><option value="2">2.0</option></select></label><label>글자 색<input id="format-color" type="color" value="#4286b5"><span><input id="format-use-color" type="checkbox"> 선택 색 적용</span></label></div><div class="writing-actions">${btn('formatApply','서식 적용','tiny','type="button"')}${btn('formatPreview','저장·미리보기','tiny','type="button"')}${btn('formatClear','직접 지정한 서식 지우기','ghost tiny','type="button"')}</div><p id="formatting-notice" class="muted">기존 글의 관측 기록은 학습 자료실에서 볼 수 있어요. 네이버 적용은 실제 편집기에서 따로 검증합니다.</p><div id="formatting-preview" class="formatting-preview" aria-label="꾸미기 미리보기">원고를 저장하면 미리보기가 나타나요.</div></div></details>`;}
async function refreshFormattingPreview(){const target=document.getElementById('formatting-preview'),item=S.items.find(i=>i.id===editing);if(!target||!item)return;const doc=await api('/api/formatting-agent?itemId='+encodeURIComponent(item.id));if(!target.isConnected||document.getElementById('draft')?.value!==item.draft||doc.draftHash!==await formattingDraftHash(item.draft))return;target.innerHTML=formattingHTML(doc);document.getElementById('formatting-notice').textContent=doc.stalePlan?'원고가 바뀌어 이전 서식은 적용되지 않아요. 새 위치에 다시 지정해 주세요.':(doc.profileName?doc.profileName+' · ':'')+doc.notice;}
async function applyWriterFormatting(){const draft=document.getElementById('draft'),selection={...draftSelection},style={},value=id=>document.getElementById(id).value,target=value('format-target'),kind=value('format-kind'),profileId=value('format-profile');if(value('format-size'))style.fontSizePx=Number(value('format-size'));if(value('format-bold'))style.bold=value('format-bold')==='true';if(value('format-align'))style.alignment=value('format-align');if(value('format-lineheight'))style.lineHeight=Number(value('format-lineheight'));if(document.getElementById('format-use-color').checked)style.color=value('format-color');if(target==='selection'&&(selection.start===selection.end||!Object.keys(style).length)){toast('원고에서 문장을 선택하고 적용할 글자 서식을 골라 주세요.');return;}const cursor=selection.start,source=draft.value,item=await saveWriter(),doc=await api('/api/formatting-agent?itemId='+encodeURIComponent(item.id)),input={itemId:item.id,draftHash:doc.draftHash,profileId:profileId||null};if(doc.draftHash!==await formattingDraftHash(source)){toast('원고가 다른 곳에서 바뀌었어요. 최신 원고를 확인해 주세요.');return;}if(target==='selection'){if(style.alignment||style.lineHeight){toast('정렬·줄 간격은 문단을 대상으로 적용해 주세요.');return;}input.range={...selection,style};}else{const block=doc.blocks.find(p=>p.start<=cursor&&p.end>=cursor)||doc.blocks.find(p=>p.start>=cursor)||doc.blocks.at(-1);if(!block||item.draft!==source){toast('꾸밀 문단에 커서를 놓아 주세요.');return;}input.paragraph={index:block.index,kind,style};}await act('saveFormatting',input,'원고 내용과 별도로 서식을 저장했어요.');await refreshFormattingPreview();}
function formattingLearningPanel(){if(!formatting.studies.length)return '';return panel('써즈 꾸미기 관측 기록',`<div class="panel-body">${formatting.profiles.map(p=>`<div class="mini-row"><div><strong>${esc(p.name)}</strong><p>${p.sampleCount}개 글 확인 · ${Object.keys(p.body).length||Object.keys(p.heading).length?'정확히 확인한 서식 적용':'글자 크기·색상 정확한 값은 확인 대기'}</p></div></div>`).join('')}${formatting.studies.map(s=>`<details class="details"><summary>${esc(s.at.slice(0,10))} · 기존 글 ${s.posts.length}개 관측</summary><div class="detail-body">${s.posts.map(p=>`<p><a href="${esc(p.url)}" target="_blank" rel="noopener">${esc(p.title)}</a> · ${p.bodyMethod==='computed'?'계산된 서식 확인':'화면 관측 · 정확한 수치 확인 대기'}</p>`).join('')}${s.commonPatterns.map(x=>`<p>${esc(x)}</p>`).join('')}${s.warnings.map(x=>`<p class="muted">${esc(x)}</p>`).join('')}</div></details>`).join('')}</div>`);}
for(const name of ['select','keyup','mouseup'])document.addEventListener(name,e=>{if(e.target.id==='draft')draftSelection={start:e.target.selectionStart,end:e.target.selectionEnd};});
document.addEventListener('pointerdown',e=>{if(e.target.closest('.formatting-tools')&&document.activeElement?.id==='draft'){const d=document.activeElement;draftSelection={start:d.selectionStart,end:d.selectionEnd};}});
document.addEventListener('input',e=>{if(e.target.id==='draft'){const note=document.getElementById('formatting-notice');if(note)note.textContent='원고가 변경됐어요. 저장·미리보기를 눌러 서식을 확인해 주세요.';}});

document.addEventListener('input',e=>{if(e.target.closest('#writer-form')&&['draft','title','minWords','keyword','keywordCount'].includes(e.target.name))refreshWriterCounts();});
